    <style>
        @page{size:A4 portrait;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#e9edf0;color:#101820;font-family:Tahoma,Arial,sans-serif}.print-toolbar{display:flex;justify-content:center;gap:8px;padding:14px;background:#17232a}.print-toolbar a,.print-toolbar button{padding:9px 14px;border:1px solid #49616b;border-radius:5px;background:transparent;color:#fff;text-decoration:none;font:600 13px Tahoma,Arial,sans-serif;cursor:pointer}.print-toolbar button{background:#00d9ed;border-color:#00d9ed;color:#071216}.sheet{width:210mm;min-height:297mm;margin:14px auto;padding:5mm 7.5mm;display:grid;grid-template-columns:repeat(3,65mm);grid-auto-rows:30mm;column-gap:2.5mm;row-gap:1.5mm;align-content:start;background:#fff;box-shadow:0 3px 18px rgba(0,0,0,.18)}.qr-card{position:relative;display:flex;align-items:center;width:65mm;height:30mm;overflow:hidden;padding:2mm;border:.25mm solid #111;border-radius:1.3mm;background:linear-gradient(135deg,#fff 0%,#f8fbfc 78%,#e8f4f6 100%);break-inside:avoid;page-break-inside:avoid}.qr-card:before{content:"";position:absolute;top:0;left:0;right:0;height:1.1mm;background:linear-gradient(90deg,#00bfd4 0%,#00e5ff 55%,#ff4d91 100%)}.qr-card:after{content:"";position:absolute;right:-4mm;bottom:-5mm;width:15mm;height:15mm;border:1px solid rgba(0,157,181,.25);border-radius:50%}.qr-box{position:relative;z-index:1;flex:0 0 25mm;width:25mm;height:25mm;display:flex;align-items:center;justify-content:center;background:#fff}.qr-box svg{display:block;width:25mm;height:25mm}.qr-info{position:relative;z-index:1;min-width:0;padding-left:2mm;border-left:.25mm solid #b7cbd0}.qr-brand{color:#168da1;font-size:2.25mm;font-weight:700;letter-spacing:.28mm;line-height:1.05;white-space:nowrap}.qr-title{margin-top:1.4mm;color:#101820;font-size:2.9mm;font-weight:700;line-height:1.08;overflow-wrap:anywhere}.qr-name{margin-top:1.2mm;color:#26383f;font-size:2.5mm;font-weight:600;line-height:1.12;overflow-wrap:anywhere}.qr-nik{margin-top:1.5mm;color:#60727a;font-size:2.2mm;line-height:1.1}.qr-nik strong{color:#101820;font-size:2.55mm;letter-spacing:.08mm}.qr-mark{position:absolute;right:2mm;top:2.1mm;color:#ff4d91;font-size:2.2mm;font-weight:700;letter-spacing:.18mm}.qr-card:nth-child(3n+1) .qr-mark{color:#00a9bd}.qr-card:nth-child(3n+2) .qr-mark{color:#ff4d91}.qr-card:nth-child(3n) .qr-mark{color:#7382dd}.print-note{text-align:center;margin:0 0 18px;color:#52646c;font-size:12px}@media print{html,body{background:#fff}.print-toolbar,.print-note{display:none}.sheet{margin:0;box-shadow:none}}@media screen and (max-width:800px){.sheet{transform-origin:top left;transform:scale(.75);margin-bottom:-74mm}.print-note{padding:0 12px}.print-toolbar{position:sticky;top:0;z-index:5}}
    </style>
